  "implementation": "def solve(case):
    capacity = case['capacity']
    trials = case['trials']
    n = len(trials)
    start = max(0, n - capacity)
    memory = []
    for i in range(start, n):
        t = trials[i]
        memory.append({
            'last_trial': i,
            'reflection': t['reflection'],
            'signature': t['signature'],
            'success': t['success']
        })
    signatures = [m['signature'] for m in memory]
    return {'memory': memory, 'signatures': signatures}
